import {
  RESET_STORY_ARGS,
  STORY_ARGS_UPDATED,
  UPDATE_STORY_ARGS,
} from "storybook/internal/core-events";
import type {
  PartialStoryFn,
  PlayFunctionContext,
  StoryContext,
} from "storybook/internal/types";
import { global as globalThis } from "@storybook/global";
import { expect, within } from "storybook/test";
function pick(obj, keys) {
  const result = {};
  for (const key of keys) {
    result[key] = obj[key];
  }
  return result;
}
export default {
  component: globalThis.__TEMPLATE_COMPONENTS__.Pre,
  args: {
    componentArg: "componentArg",
    storyArg: "componentStoryArg",
    object: { a: "component", b: "component" },
  },
  // Compose the set of  args into `object`, so the pre component only needs a single prop
  //   (selecting only the args specified on parameters.argNames if set)
  decorators: [
    (storyFn: PartialStoryFn, context: StoryContext) => {
      const { argNames } = context.parameters;
      const args = { ...context.args };
      const object = argNames ? pick(args, argNames) : args;
      return storyFn({ args: { object } });
    },
  ],
};
export const Inheritance = {
  args: { storyArg: "storyArg", object: { a: "story" } },
  play: async ({ canvasElement }: PlayFunctionContext<any>) => {
    // NOTE: these stories don't test project-level args inheritance as it is too problematic
    // to have an arg floating around that will apply too *all* other stories in our sandboxes.
    await expect(
      JSON.parse(within(canvasElement).getByTestId("pre").innerText),
    ).toEqual({
      componentArg: "componentArg",
      storyArg: "storyArg",
      object: { a: "story" },
    });
  },
};
export const Targets = {
  args: { a: "a", b: "b" },
  argTypes: { a: { target: "elsewhere" } },
  parameters: { argNames: ["a", "b"] },
  play: async ({ canvasElement }: PlayFunctionContext<any>) => {
    // Check that `a` doesn't end up set
    await expect(
      JSON.parse(within(canvasElement).getByTestId("pre").innerText),
    ).toEqual({ b: "b" });
  },
  tags: ["!vitest"],
};
export const Events = {
  args: { test: "initial" },
  parameters: { argNames: ["test"] },
  play: async ({ canvasElement, id }: PlayFunctionContext<any>) => {
    const channel = globalThis.__STORYBOOK_ADDONS_CHANNEL__;
    await channel.emit(RESET_STORY_ARGS, { storyId: id });
    await new Promise((resolve) => channel.once(STORY_ARGS_UPDATED, resolve));
    await within(canvasElement).findByText(/initial/);
    await channel.emit(UPDATE_STORY_ARGS, {
      storyId: id,
      updatedArgs: { test: "updated" },
    });
    await new Promise((resolve) => channel.once(STORY_ARGS_UPDATED, resolve));
    await within(canvasElement).findByText(/updated/);
  },
  // this story can't be reliably tested because the args changes results in renderPhases disrupting test runs
  tags: ["!vitest", "!test"],
};
Inheritance.parameters = {
  ...Inheritance.parameters,
  docs: {
    ...Inheritance.parameters?.docs,
    source: {
      originalSource:
        "{\n  args: {\n    storyArg: 'storyArg',\n    object: {\n      a: 'story',\n    },\n  },\n  play: async ({ canvasElement }: PlayFunctionContext<any>) => {\n    // NOTE: these stories don't test project-level args inheritance as it is too problematic\n    // to have an arg floating around that will apply too *all* other stories in our sandboxes.\n    await expect(JSON.parse(within(canvasElement).getByTestId('pre').innerText)).toEqual({\n      componentArg: 'componentArg',\n      storyArg: 'storyArg',\n      object: {\n        a: 'story',\n      },\n    });\n  },\n}",
      ...Inheritance.parameters?.docs?.source,
    },
  },
};
Targets.parameters = {
  ...Targets.parameters,
  docs: {
    ...Targets.parameters?.docs,
    source: {
      originalSource:
        "{\n  args: {\n    a: 'a',\n    b: 'b',\n  },\n  argTypes: {\n    a: { target: 'elsewhere' },\n  },\n  parameters: { argNames: ['a', 'b'] },\n  play: async ({ canvasElement }: PlayFunctionContext<any>) => {\n    // Check that `a` doesn't end up set\n    await expect(JSON.parse(within(canvasElement).getByTestId('pre').innerText)).toEqual({\n      b: 'b',\n    });\n  },\n  tags: ['!vitest'],\n}",
      ...Targets.parameters?.docs?.source,
    },
  },
};
Events.parameters = {
  ...Events.parameters,
  docs: {
    ...Events.parameters?.docs,
    source: {
      originalSource:
        "{\n  args: {\n    test: 'initial',\n  },\n  parameters: { argNames: ['test'] },\n  play: async ({ canvasElement, id }: PlayFunctionContext<any>) => {\n    const channel = globalThis.__STORYBOOK_ADDONS_CHANNEL__;\n    await channel.emit(RESET_STORY_ARGS, { storyId: id });\n    await new Promise((resolve) => channel.once(STORY_ARGS_UPDATED, resolve));\n\n    await within(canvasElement).findByText(/initial/);\n\n    await channel.emit(UPDATE_STORY_ARGS, { storyId: id, updatedArgs: { test: 'updated' } });\n    await new Promise((resolve) => channel.once(STORY_ARGS_UPDATED, resolve));\n    await within(canvasElement).findByText(/updated/);\n  },\n  // this story can't be reliably tested because the args changes results in renderPhases disrupting test runs\n  tags: ['!vitest', '!test'],\n}",
