  parameters: {
    component: JsFunctionComponentInlineDefaultsNoPropTypesComponent,
  },
};
export const JsDefaultValues = {
  parameters: { component: JsDefaultValuesComponent },
};
export const JsReactMemo = { parameters: { component: JsReactMemoComponent } };
