    source: {
      originalSource:
        "{\n  parameters: { component: JsFunctionComponentInlineDefaultsComponent },\n}",
      ...JsFunctionComponentInlineDefaults.parameters?.docs?.source,
    },
  },
};
JsFunctionComponentInlineDefaultsNoPropTypes.parameters = {
